import { useState } from "react";

export function DropTargetState({
  label = "{{label}}",
  accent = "{{accent}}",
  force = {{force}},
  radius = {{radius}},
}) {
  const [live, setLive] = useState(false);
  const active = force || live;
  return (
    <div>
      <div
        onDragOver={(e) => { e.preventDefault(); setLive(true); }}
        onDragLeave={() => setLive(false)}
        onDrop={(e) => { e.preventDefault(); setLive(false); }}
        style={{
          width: 260, boxSizing: "border-box", display: "flex", flexDirection: "column", alignItems: "center", gap: 8,
          font: "14px/1.5 system-ui, sans-serif", background: active ? `color-mix(in srgb, ${accent} 14%, #FAF7F2)` : "#FAF7F2",
          color: active ? "#241430" : "#24143099", border: `2.5px dashed ${active ? accent : "#24143035"}`,
          borderRadius: radius, padding: "30px 16px", textAlign: "center",
        }}
      >
        <svg width="26" height="26" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v11m0-11 4 4m-4-4-4 4M5 16v3a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-3" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg>
        <span>{label}</span>
      </div>
      <p style={{ width: 260, margin: "8px 0 0", fontSize: 11, color: "#241430888" }}>No CSS pseudo-class exists for this either — drag something over the zone to fire real drag events, or force the accepting look with the <code>force</code> prop.</p>
    </div>
  );
}
